# --------------------------------
# Write a simulated .fastq.gz file
# --------------------------------

srq.test <- makeFakeSRQ(Biostrings::DNAStringSet(c(rep("", 33),  # WT            AGCGAATTAGAG
                                  rep("", 24),  # WT            CTCGAATTAGTA
                                  rep("", 11),  # 2 base change TTTAGCGCGTAG
                                  rep("", 8),       # -4, internal  GGCGTATTAACC
                                  rep("", 7),        # -5, 3' end    CATGTGGCACGC
                                  rep("", 6),  # +1 insertion  CTTATGACGCTC
                                  rep("", 4),  # +1 ins, 1 bc  TCCAGGGTATTC
                                  rep("", 8),       # f primer del  AATAAGTCATTA
                                  rep("", 4),      # r primer del  CCCATCACAAAG
                                  rep("", 5),   # umi error     GGCGTGAAAGAG
                                  rep("", 3),   # barcode error CCTAACTCAGGA
                                  rep("", 3),      # -4, +1        CTTAGGGCATGT
                                  rep("", 2)    # < reads       GTTATGTTGTTA
)))
if (file.exists(file.path(tempdir(), "test-merged.fastq.gz"))) {file.remove(file.path(tempdir(), "test-merged.fastq.gz"))}
ShortRead::writeFastq(srq.test, file = file.path(tempdir(), "test-merged.fastq.gz"))


srq.test.lowdiv <- makeFakeSRQ(Biostrings::DNAStringSet(rep("", 33)))
if (file.exists(file.path(tempdir(), "test-merged-lowdiv.fastq.gz"))) {file.remove(file.path(tempdir(), "test-merged-lowdiv.fastq.gz"))}
